/* Explicit, manually advanced UX rehearsals. No API/model or business-data writes. */
let rehearsals=[];
try{const saved=JSON.parse(sessionStorage.getItem('cockpit-rehearsals-v1')||'[]');if(Array.isArray(saved))rehearsals=saved.filter(x=>x&&['conversion','content'].includes(x.kind)&&Array.isArray(x.rows)&&Array.isArray(x.events));}catch{}
const rehearsalNames={conversion:'转化核验演练',content:'内容审核演练'};
const rehearsalStates={draft:'待确认',active:'待推进演练',evidence:'结果待复核',verified:'本次已确认',cancelled:'已取消'};
function rehearsalButton(label,action,id=''){return `<button data-rehearsal="${action}" data-id="${esc(id)}">${label}</button>`;}
function rehearsalSave(){try{sessionStorage.setItem('cockpit-rehearsals-v1',JSON.stringify(rehearsals));}catch{toast('存储不可用，演练仅保留在当前页面。');}renderTasks();renderPanorama();}
function rehearsalSources(kind,scope=pSnapshot()){return kind==='content'?pRows('content',scope).filter(r=>r.status==='待审核').map(r=>({id:r.id,title:r.title,result:'待审核'})):pRows('paid',scope).flatMap(r=>Array.from({length:r.conversions},(_,i)=>({id:`${r.id}/转化${i+1}`,source:r.id,title:`${r.date} · ${r.topic}`,result:'待核验'})));}
function rehearsalEntry(){showDialog('REHEARSAL / 执行演练',`<div class="p-detail"><h2>选择要推进的工作</h2><p>${pScope()} · 当前范围会固定到任务中。</p><div class="rehearsal-choices">${['conversion','content'].map(k=>`<div><h3>${rehearsalNames[k]}</h3><b>${rehearsalSources(k).length} 条待处理</b><p>${k==='conversion'?'逐条检查模拟转化质量，复核并确认分类结果。':'检查待审核文章，复核通过项与需补充项。审核不等于发布。'}</p>${rehearsalButton('选择这条演练','new',k)}</div>`).join('')}</div><p>这两条流程由你手动推进，结果是演练设定。不会调用业务接口或修改原始数据。</p></div>`);}
function rehearsalForm(kind,id=''){const old=rehearsals.find(t=>t.id===id),scope=old?.scope||pSnapshot(),rows=old?.rows||rehearsalSources(kind,scope);if(!rows.length){showDialog('REHEARSAL / 当前范围',`<div class="p-detail"><h2>当前范围没有待处理记录</h2><p>${pScope(scope)}</p><p>请调整日期或主题，再开始${rehearsalNames[kind]}。</p></div>`);return;}const duplicate=!old&&rehearsals.find(t=>t.kind===kind&&pScope(t.scope)===pScope(scope)&&!['cancelled','verified'].includes(t.status));if(duplicate){rehearsalShow(duplicate.id);toast('这个范围已有未完成演练，可继续处理。');return;}
 showDialog('CONFIRM / 确认指令',`<div class="p-detail"><h2>${old?'修改':'确认'}${rehearsalNames[kind]}</h2><p>${pScope(scope)} · ${rows.length} 条 · 范围固定</p><form id="rehearsalForm" data-kind="${kind}" data-id="${esc(id)}" data-scope="${esc(JSON.stringify(scope))}"><label>负责人<input name="owner" required maxlength="60" value="${esc(old?.owner||'客户运营负责人')}"></label><label>复核日期<input name="due" type="date" required value="${old?.due||'2026-09-08'}"></label><label>补充要求<textarea name="note" aria-label="补充要求" rows="3" maxlength="1000">${esc(old?.note||'保留逐条结果；证据不足的条目单独列出，不直接认定通过。')}</textarea></label><p>确认后进入演练队列，仍可修改要求或取消。实际业务数据保持不变。</p><button class="primary-button" type="submit">${old?'保存要求':'确认并加入演练'}</button></form></div>`);}
function rehearsalCounts(t){return t.rows.reduce((a,r)=>(a[r.result]=(a[r.result]||0)+1,a),{});}
function rehearsalShow(id){const t=rehearsals.find(x=>x.id===id);if(!t)return;const report=['evidence','verified'].includes(t.status),options=t.kind==='content'?['审核通过','需补充']:['有效意向（模拟）','重复记录（模拟）','需补充证据'];showDialog('EXECUTION / 演练记录',`<div class="p-detail rehearsal-detail"><div class="rehearsal-tag">${rehearsalStates[t.status]} · 手动演练</div><h2>${rehearsalNames[t.kind]}</h2><p>${pScope(t.scope)} · ${t.rows.length} 条<br>${esc(t.owner)} · ${t.due} 复核</p><div class="rehearsal-stages">${['确认范围','推进处理','复核发现','确认本轮结果'].map((l,i)=>`<span class="${i<=({active:1,evidence:2,verified:3,cancelled:0})[t.status]?'on':''}">${i+1} ${l}</span>`).join('')}</div><p><b>你的要求：</b>${esc(t.note||'无补充要求')}</p>${t.status==='active'?`<div class="rehearsal-notice">已固定 ${t.rows.length} 条记录。点击下方按钮，生成一批明确标注的模拟发现；你可以逐条修改和复核。</div>${rehearsalButton('推进演练，查看模拟发现','advance',id)} ${rehearsalButton('修改要求','edit',id)} ${rehearsalButton('取消待执行演练','cancel',id)}`:''}${report?`<div class="rehearsal-metrics">${Object.entries(rehearsalCounts(t)).map(([l,n])=>`<div><b>${n}</b><span>${l}</span></div>`).join('')}</div><form id="rehearsalReview" data-id="${id}"><div class="p-table-scroll">${table(['记录 / 对象','演练发现','复核分类'],t.rows.map((r,i)=>[`${esc(r.id)}<br>${esc(r.title)}`,esc(r.reason),t.status==='evidence'?`<select name="row-${i}" aria-label="${esc(r.id)}复核分类">${options.map(o=>`<option ${r.result===o?'selected':''}>${o}</option>`).join('')}</select>`:esc(r.result)]))}</div>${t.status==='evidence'?'<p>可修改分类后确认。修改是原型中的人工复核，不会生成真实证据。</p><button class="primary-button" type="submit">确认本轮结果并回到大盘</button>':`<p>本轮结果已留存。${t.kind==='content'?'审核通过项仍待发布；需补充项继续跟进。':'需补充证据的转化仍未定论；模拟分类不能用来计算真实获客成本。'}</p>${rehearsalButton('为未解决项拟定跟进','follow',id)}`}</form>`:''}${t.status==='cancelled'?'<p>演练已取消，原始数据未改变；已确认的范围和操作记录仍保留。</p>':''}<details class="rehearsal-events"><summary>查看指令与变更记录（${t.events.length}）</summary>${t.events.map(e=>`<p>${esc(e)}</p>`).join('')}</details><div class="d-chat-actions">${rehearsalButton('回到这个业务范围','return',id)}${rehearsalButton('向助手询问进度','discuss',id)}</div></div>`);}
function rehearsalSummary(t){const counts=rehearsalCounts(t);return `${rehearsalNames[t.kind]}：${rehearsalStates[t.status]}。${['evidence','verified'].includes(t.status)?Object.entries(counts).map(([l,n])=>`${l} ${n} 条`).join('；'):`范围 ${t.rows.length} 条，${t.status==='cancelled'?'已取消，记录保留':'等待手动推进'}。`}`;}
function rehearsalRender(){let strip=$('#rehearsalStrip');if(!strip){strip=document.createElement('section');strip.id='rehearsalStrip';strip.className='rehearsal-strip';panoPage.querySelector('.p-grid')?.before(strip);}const latest=rehearsals[0];strip.innerHTML=`<div><span class="rehearsal-tag">指令演练</span><b>${latest?esc(rehearsalSummary(latest)):'把核查指令推进到可复核的结果'}</b><small>${latest?'固定范围：'+pScope(latest.scope):'确认 → 处理 → 复核 → 结果；不修改原始指标'}</small></div><div>${latest?rehearsalButton('继续 / 查看结果','show',latest.id):''}${rehearsalButton('启动演练','entry')}</div>`;const complete=rehearsals.filter(t=>t.status==='verified'&&pScope(t.scope)===pScope());const latestContent=complete.find(t=>t.kind==='content'),latestConversion=complete.find(t=>t.kind==='conversion');for(const [key,t] of [['content',latestContent],['funnel',latestConversion]]){if(!t)continue;const body=panoPage.querySelector(`[data-card="${key}"] .p-body`);if(body)body.insertAdjacentHTML('beforeend',`<div class="rehearsal-overlay"><span>已确认的演练结果</span><b>${Object.entries(rehearsalCounts(t)).map(([l,n])=>`${l} ${n}`).join(' · ')}</b>${rehearsalButton('查看记录','show',t.id)}<small>原始数据未改写${key==='content'?' · 审核通过不等于发布':''}</small></div>`);}}
const rehearsalRenderBase=renderPanorama;renderPanorama=function(){rehearsalRenderBase();rehearsalRender();};
const rehearsalAllTasks=allTasks;allTasks=function(){return [...rehearsals.map(t=>({id:t.id,title:rehearsalNames[t.kind]+' · 手动演练',status:t.status,issue:t.kind==='content'?'images':'allocation',owner:t.owner,due:t.due,note:t.note,evidence:rehearsalSummary(t),criterion:'逐条复核模拟发现，保留未解决项；不冒充真实执行。',progress:rehearsalStates[t.status]})),...rehearsalAllTasks()];};
const rehearsalShowTask=showTask;showTask=function(id){if(rehearsals.some(t=>t.id===id)){rehearsalShow(id);return;}rehearsalShowTask(id);};
const rehearsalTaskRender=renderTasks;renderTasks=function(){rehearsalTaskRender();$$('#taskList .task-row').forEach(row=>{const t=rehearsals.find(x=>x.id===row.dataset.task);if(!t)return;row.querySelector('.eyebrow').textContent=t.id+' · 当前标签页手动演练';row.querySelector('.task-right').innerHTML=`<span class="badge">${rehearsalStates[t.status]} · 演练</span><small>查看模拟发现与操作记录 ↗</small>`;});if(rehearsals.length){const labels=['待确认方案','正在处理','等待检查结果','本次检查已确认'];$$('#ledgerSummary .summary-cell span').forEach((el,i)=>el.textContent=labels[i]);}};
document.addEventListener('submit',e=>{if(e.target.id==='rehearsalForm'){e.preventDefault();const f=e.target;if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));data.owner=data.owner.trim();if(!data.owner){toast('请填写负责人。');return;}const existing=rehearsals.find(t=>t.id===f.dataset.id);if(existing){Object.assign(existing,data);existing.events.push('修改要求：'+data.note+'；负责人 '+data.owner+'；复核 '+data.due);rehearsalSave();rehearsalShow(existing.id);return;}const scope=JSON.parse(f.dataset.scope),kind=f.dataset.kind,t={...data,kind,scope,id:'DRILL-'+Date.now().toString(36).toUpperCase(),status:'active',rows:rehearsalSources(kind,scope),events:['已确认范围：'+pScope(scope),'已加入手动演练队列，未调用业务接口']};rehearsals.unshift(t);rehearsalSave();rehearsalShow(t.id);addMessage('assistant',`<p><strong>${rehearsalNames[kind]}</strong>已加入演练队列，共 ${t.rows.length} 条。你可以修改要求、取消，或推进到模拟发现。</p>${rehearsalButton('查看演练进度','show',t.id)}`);}else if(e.target.id==='rehearsalReview'){e.preventDefault();const t=rehearsals.find(x=>x.id===e.target.dataset.id);if(!t||t.status!=='evidence')return;const data=new FormData(e.target);t.rows.forEach((r,i)=>{const next=data.get('row-'+i);if(next!==r.result)t.events.push('复核调整：'+r.id+'，'+r.result+' → '+next);r.result=next;});t.status='verified';t.events.push('客户确认本轮演练分类；原始业务数据保持不变。');rehearsalSave();closeDialog();decision.active=null;decision.allCharts=true;Object.assign(pano,t.scope);navigate('panorama');showChat();addMessage('assistant',`<p><strong>本轮演练已确认。</strong>${esc(rehearsalSummary(t))}</p><p>${t.kind==='content'?'通过项等待发布，需补充项继续跟进。':'仍需补充证据的条目保留为未解决。'}结果已回到大盘的演练区域和待办与进度。</p>${rehearsalButton('查看结果与变更记录','show',t.id)}`);$('#rehearsalStrip')?.scrollIntoView({block:'nearest',behavior:'smooth'});}});
window.addEventListener('click',e=>{const b=e.target.closest('[data-rehearsal]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.rehearsal,id=b.dataset.id,t=rehearsals.find(x=>x.id===id);if(a==='entry'){rehearsalEntry();return;}if(a==='new'){rehearsalForm(id);return;}if(!t)return;if(a==='show')rehearsalShow(id);if(a==='edit'&&t.status==='active')rehearsalForm(t.kind,id);if(a==='advance'&&t.status==='active'){t.rows.forEach((r,i)=>{r.result=t.kind==='content'?(i%3===0?'需补充':'审核通过'):['需补充证据','重复记录（模拟）','有效意向（模拟）','有效意向（模拟）'][i%4];r.reason=t.kind==='content'?(i%3===0?'演练设定：关键事实缺少出处，需补充。':'演练设定：事实与表达检查通过，尚未发布。'):(i%4===0?'演练设定：缺少跟进证据。':i%4===1?'演练设定：重复来源，需人工确认。':'演练设定：采购意向符合条件。');});t.status='evidence';t.events.push('手动推进：已生成模拟发现，等待逐条复核。');rehearsalSave();rehearsalShow(id);}if(a==='cancel'&&t.status==='active'){t.status='cancelled';t.events.push('客户取消待执行演练。');rehearsalSave();rehearsalShow(id);}if(a==='return'){closeDialog();decision.active=null;decision.allCharts=true;Object.assign(pano,t.scope);navigate('panorama');}if(a==='discuss'){closeDialog();showChat();addMessage('user','这项演练进展怎样？');addMessage('assistant',`<p>${esc(rehearsalSummary(t))}</p><p>负责人：${esc(t.owner)}；复核日期：${t.due}。${t.status==='evidence'?'下一步需要你复核分类后确认。':t.status==='active'?'尚未生成模拟发现，你可以推进或修改要求。':'变更记录已保留。'}</p>${rehearsalButton('回到演练记录','show',id)}`);}if(a==='follow'){pPlan(t.kind==='content'?'content':'verify');const f=$('#pPlanForm');f.elements.note.value=`来源演练：${id}。${rehearsalSummary(t)}。继续跟进未解决项。`;}} ,true);
const rehearsalReply=reply;reply=function(q){if(/^(启动|开始)(转化核验|内容审核)(演练)?$/.test(q)){addMessage('user',q);rehearsalForm(q.includes('内容')?'content':'conversion');return;}if(rehearsals.length&&/^(演练进度|刚才的演练怎么样|查看演练结果)/.test(q)){addMessage('user',q);rehearsalShow(rehearsals[0].id);return;}rehearsalReply(q);};
document.addEventListener('change',e=>{const form=e.target.closest('#rehearsalReview');if(!form)return;const counts={};form.querySelectorAll('select').forEach(s=>counts[s.value]=(counts[s.value]||0)+1);const metrics=$('.rehearsal-metrics');if(metrics)metrics.innerHTML=Object.entries(counts).map(([l,n])=>`<div><b>${n}</b><span>${esc(l)} · 待确认</span></div>`).join('');});
resetChat();renderTasks();
